import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.*; import ghidra.program.model.address.*; import java.io.*;
public class VerifyAsm extends GhidraScript { public void run() throws Exception { String out=getScriptArgs()[0]; try(PrintWriter pw=new PrintWriter(out)){ for(long[] r: new long[][]{{0x1f10c8,0x1f10d4},{0x174ba0,0x174ba8},{0x1751ac,0x1751b8},{0x1ad928,0x1ad934},{0x1ad9c4,0x1ad9d0},{0x3d6fe8,0x3d704c},{0x3d704c,0x3d70d8},{0x3d70d8,0x3d711c},{0x3d711c,0x3d7140},{0x3d7140,0x3d7164},{0x3d7164,0x3d7188}}){ Address a=toAddr(r[0]); clearListing(a,toAddr(r[1])); disassemble(a); while(a.getOffset()<r[1]){ Instruction in=getInstructionAt(a); pw.printf("%s %s\n",a,in); a=a.add(in!=null?in.getLength():4);} pw.println(); } } } }
